/**
 * LEGACY SERVICE WORKER — cleanup only.
 *
 * This file replaced the old "cache everything naively" service worker that
 * was causing two problems:
 *   1. It conflicted with the Workbox SW generated by vite-plugin-pwa.
 *   2. It blindly cached authenticated API responses (a security risk).
 *
 * This version does nothing except:
 *   - Delete the old 'nuvana360-v1' cache created by the previous SW.
 *   - Unregister itself so the Workbox SW (registered automatically by
 *     vite-plugin-pwa at /nuvana360/sw.js) has sole control.
 *
 * Users who had the old SW will receive this version on their next visit and
 * the cleanup will happen transparently in the background.
 */

const LEGACY_CACHE_NAME = 'nuvana360-v1';

self.addEventListener('install', () => {
  // Skip waiting so this SW activates immediately and can clean up.
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      // 1. Delete the old cache if it exists.
      try {
        await caches.delete(LEGACY_CACHE_NAME);
      } catch (_) {
        // Ignore — cache may not exist on fresh installs.
      }

      // 2. Unregister this SW so the Workbox SW takes full control.
      //    After unregistration the browser will no longer run this file.
      await self.registration.unregister();

      // 3. Tell all open tabs to reload so the Workbox SW is picked up.
      const clients = await self.clients.matchAll({ type: 'window' });
      clients.forEach((client) => client.navigate(client.url));
    })()
  );
});

// No fetch handler — this SW must not intercept any requests.
